import { defineConfig } from "oxlint";
import antiSlop from "ultracite/oxlint/anti-slop";
import core from "ultracite/oxlint/core";
import { jsPluginSettings, selectJsPlugins } from "ultracite/oxlint/js-plugins";
import next from "ultracite/oxlint/next";
import nextJsPlugins from "ultracite/oxlint/next/js-plugins";
import react from "ultracite/oxlint/react";
import shadcn from "ultracite/oxlint/shadcn";

const jsPlugins = selectJsPlugins([
  "github",
  "sonarjs",
  "tsdoc",
  "react-doctor",
]);

// shadcn/ui components are generated by the CLI and re-generated on `shadcn add`,
// so they intentionally don't follow every stylistic rule. Keep correctness and
// accessibility checks, but relax the style rules the generator violates.
const shadcnOverrides = {
  overrides: [
    {
      files: ["**/components/ui/**/*.{ts,tsx}"],
      rules: {
        "func-style": "off",
        "react-doctor/only-export-components": "off",
        "react/function-component-definition": "off",
        "sonarjs/no-wildcard-import": "off",
        "sort-keys": "off",
      },
    },
    {
      // `Label` is a thin wrapper around `<label>` that forwards every prop,
      // including `htmlFor`. The association with a control is only visible at
      // the call site, which the rule cannot see from here.
      files: ["**/components/ui/label.tsx"],
      rules: {
        "jsx-a11y/label-has-associated-control": "off",
      },
    },
    {
      // The generated `InputGroup` wraps its controls in a `role="group"` div
      // and makes the whole addon a click target that focuses the input. Both
      // are generator idioms: the field is still reachable by keyboard on its
      // own, so the extra mouse affordance and ARIA grouping are not barriers.
      files: ["**/components/ui/input-group.tsx"],
      rules: {
        "anti-slop/require-safety-comment-for-type-assertion": "off",
        "import/consistent-type-specifier-style": "off",
        "jsx-a11y/click-events-have-key-events": "off",
        "jsx-a11y/no-noninteractive-element-interactions": "off",
        "jsx-a11y/prefer-tag-over-role": "off",
      },
    },
  ],
};

export default defineConfig({
  extends: [
    core,
    react,
    next,
    nextJsPlugins,
    shadcn,
    antiSlop,
    jsPlugins,
    shadcnOverrides,
  ],
  ignorePatterns: core.ignorePatterns,
  jsPlugins: [...jsPlugins.jsPlugins, ...shadcn.jsPlugins],
  settings: jsPluginSettings,
});
